// Cloudflare Worker entry. Wraps the OpenNext worker with an edge cache for anonymous
// page views, so bots and logged-out visitors do not trigger Next.js rendering and
// Supabase queries on every hit. Logged-in users (sb-* cookie) always bypass the cache.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";
// @ts-expect-error generated by `opennextjs-cloudflare build`
export * from "./.open-next/worker.js";

const TTL_SECONDS = 300;

type Env = {
  CF_VERSION_METADATA?: { id: string };
  NEXT_PUBLIC_SUPABASE_URL?: string;
  NEXT_PUBLIC_SUPABASE_ANON_KEY?: string;
};

export default {
  async fetch(request: Request, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }): Promise<Response> {
    const url = new URL(request.url);
    const cacheable =
      request.method === "GET" &&
      !request.headers.get("cookie")?.includes("sb-") &&
      !url.pathname.startsWith("/api/") &&
      !url.pathname.startsWith("/auth/") &&
      !url.pathname.startsWith("/admin") &&
      !url.pathname.startsWith("/_next/") &&
      !url.pathname.startsWith("/login") &&
      !url.pathname.startsWith("/following");

    if (!cacheable) return openNext.fetch(request, env, ctx);

    const cache = (caches as unknown as { default: Cache }).default;
    // Key includes the deployed version so a deploy never serves HTML that points at old chunks.
    const key = new Request(`${url.toString()}#v=${env.CF_VERSION_METADATA?.id ?? "dev"}`, { method: "GET" });
    const hit = await cache.match(key);
    if (hit) return hit;

    const res: Response = await openNext.fetch(request, env, ctx);
    if (res.status !== 200 || res.headers.has("set-cookie")) return res;

    const out = new Response(res.body, res);
    out.headers.set("cache-control", `public, max-age=60, s-maxage=${TTL_SECONDS}`);
    ctx.waitUntil(cache.put(key, out.clone()));
    return out;
  },

  // Daily keep-alive (cron trigger in wrangler.jsonc). Supabase free projects pause after
  // about a week of no activity; one tiny read per day keeps the project awake.
  async scheduled(_event: unknown, env: Env): Promise<void> {
    if (!env.NEXT_PUBLIC_SUPABASE_URL || !env.NEXT_PUBLIC_SUPABASE_ANON_KEY) return;
    const res = await fetch(`${env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/agents?select=profile_id&limit=1`, {
      headers: { apikey: env.NEXT_PUBLIC_SUPABASE_ANON_KEY },
    });
    console.log(`keepalive supabase status ${res.status}`);
  },
};
